const hour = $now.setZone('America/Fortaleza').hour;
let contexto = '';
if (hour === 7) contexto = 'Faltam 5 minutos para os Estudos Técnicos (07:30 - 09:15). Foco em APIs e Webhooks. Explique COMO praticar e ONDE abrir (ex: Postman, n8n ou webhook.site).';
else if (hour === 9) contexto = 'Faltam 5 minutos para o Treino de Musculação (09:30 - 11:30). Incentive a deixar as telas de lado, focar na hidratação e no cuidado com o corpo.';
else if (hour === 15) contexto = 'Hora de retomar com tudo! Projetos Práticos e Portfólio (15:30 - 17:30). Oriente a abrir o n8n ou GitHub e avançar em um fluxo real com documentação.';
else if (hour === 17) contexto = 'Mercado e Prospecção de Vagas CX/Suporte N2/N3 (17:30 - 19:00). Oriente a abrir o LinkedIn Jobs, buscar vagas de CX Ops/Suporte N2 e personalizar as candidaturas com carinho.';
else if (hour === 18 || hour === 19) contexto = 'Expansão Intelectual (19:00 - 20:00). Escolha uma opção para hoje (leitura, curso ou palestra). Diga exatamente o título ou tema e onde acessar.';
else contexto = 'Check-in amigável e acolhedor sobre o dia.';
return [{ json: { contexto, hour } }];
